using UnityEngine;using UnityEditor;using System;public static class VisualShaderValidation{public static string Run(){foreach(var name in new[]{"EmberFlame","AshenMembrane"}){var s=AssetDatabase.LoadAssetAtPath<Shader>("Assets/Resources/Presentation/"+name+".shader");if(!s||!s.isSupported)throw new Exception(name+" unsupported");foreach(var m in ShaderUtil.GetShaderMessages(s))if(m.severity.ToString()=="Error")throw new Exception(m.message);}return "Both URP shaders supported; no shader errors";}}
